{
    char *end;
    if (!isdigit((unsigned char)*s))
        return 0;
    errno = 0;
    unsigned long long n = strtoull(s, &end, 10);
    if (errno)
        return 0;

    unsigned long long mult = 1;
    switch (*end) {
    case 'g':
    case 'G':
        mult *= 1024;
    case 'm':
    case 'M':
        mult *= 1024;
    case 'k':
    case 'K':
